def norm(a):
    return (a + 180.0) % 360.0 - 180.0

def clamp(v):
    if v > 1.0:
        return 1.0
    if v < -1.0:
        return -1.0
    return v

def drive(me, enemy, arena):
    try:
        if not me.can_drive:
            return (0.0, 0.0)

        d = distance_to(enemy.x, enemy.y)
        wd = distance_to(0.0, 0.0)

        if wd > 5.8:
            target = bearing_to(0.0, 0.0)
            diff = norm(target - me.heading)
            base = 0.55
            turn = diff / 20.0
            if turn > 1.0:
                turn = 1.0
            if turn < -1.0:
                turn = -1.0
            return (clamp(base - turn), clamp(base + turn))

        if d < 0.8:
            away = norm(bearing_to(enemy.x, enemy.y) + 180.0)
            diff = norm(away - me.heading)
            base = -0.35
            turn = diff / 60.0
            if turn > 0.4:
                turn = 0.4
            if turn < -0.4:
                turn = -0.4
            return (clamp(base - turn), clamp(base + turn))

        target = bearing_to(enemy.x, enemy.y)
        diff = norm(target - me.heading)

        if d < 1.2:
            base = 0.30
        elif d < 2.5:
            base = 0.60
        else:
            base = 0.80

        if abs(diff) < 4.0:
            turn = 0.0
        else:
            turn = diff / 20.0
            if turn > 1.0:
                turn = 1.0
            if turn < -1.0:
                turn = -1.0

        return (clamp(base - turn), clamp(base + turn))
    except Exception:
        return (0.0, 0.0)

