def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)

    error = bearing_to(enemy.x, enemy.y)
    distance = distance_to(enemy.x, enemy.y)

    steer = error / 55.0 - me.turn_rate / 180.0
    steer = max(-1.0, min(1.0, steer))

    if abs(error) > 105:
        throttle = 0.0
    elif abs(error) > 65:
        throttle = 0.15
    elif abs(error) > 35:
        throttle = 0.45
    else:
        throttle = 1.0

    if distance < 1.0 and abs(error) < 25:
        throttle = 0.35

    left = max(-1.0, min(1.0, throttle - steer))
    right = max(-1.0, min(1.0, throttle + steer))
    return (left, right)


def weapons(me, enemy, arena):
    if me.righting or me.airborne:
        return None

    if me.inverted:
        return self_right()

    weapon = me.weapons.get("front")
    if weapon is None or weapon["type"] != "flipper":
        return None

    if not weapon["ready"] or weapon["shots_left"] <= 0:
        return None

    if enemy.airborne or enemy.righting or enemy.on_side or enemy.held or enemy.lifted:
        return None

    distance = distance_to(enemy.x, enemy.y)
    error = bearing_to(enemy.x, enemy.y)
    lateral = abs(distance * sin(radians(error)))
    reach = me.length * 0.5 + enemy.length * 0.5 + 0.32
    lateral_limit = (me.width + enemy.width) * 0.5

    if distance < reach and abs(error) < 30 and lateral < lateral_limit:
        return flip("front")

    return None

